import test from 'node:test';
import assert from 'node:assert/strict';
import {parseCount,parseRanking,parseDetail,parseSearch,routeData,IncompletePageError} from '../src/parser.js';
import {HongguoClient,resolveConfig,deduplicate,thresholdStatus} from '../src/client.js';
import {apply} from '../src/index.js';
const origin='https://hongguoduanju.com';
const stamp='2026-10-02T09:00:00Z';
const html=(route,data)=>`<script>_ROUTER_DATA = ${JSON.stringify({loaderData:{[route]:data}})};</script>`;
const row=(id='123',favorite='124.3万收藏',rank=1)=>({seriesId:id,title:'样例短剧',rank,favoriteText:favorite,likeText:'10万点赞',heatText:'200万热度',episodeVids:['1','2'],tags:['爱情'],description:'介绍'});
const ranking=(page=1,totalPages=1,rows=[row('123','124.3万收藏',(page-1)*20+1)],board='hot-drama')=>html(`rank_${board}/page`,{pageNum:page,updatedText:'10月2日已更新',content:{isSuccess:true,rankList:rows,pagination:{pageNum:page,totalPages}}});
const detail=(id='123')=>html('detail_page',{isSuccess:true,seriesDetail:{series_id:id,series_name:'样例',episode_cnt:20,tags:[],celebrities:[]},seriesSocialInfo:{series_favorite_count:'1200123',series_like_count:'900',hot_score_data:{score:'2001',text:'2001热度'}}});
const search=(q='剧')=>html('search_(keyword)/page',{isSuccess:true,query:q,totalCount:'100',searchList:[{doc_type:23,video_data:{series_id:'123',series_title:'样例',favorite_text:'120万收藏'}}]});
const resp=(body,opts={})=>new Response(body,{headers:{'content-type':'text/html'},...opts});
const opts={board:'hot-drama',page:1,sourceUrl:origin+'/rank/hot-drama',fetchedAt:stamp};
const client=(fetch,config={})=>new HongguoClient({requestIntervalMs:0,...config},{fetch});
test('count values retain display precision',()=>{assert.deepEqual(parseCount('124.3万收藏'),{raw:'124.3万收藏',value:1243000,approximate:true,precisionStep:1000});assert.equal(parseCount('0收藏').value,0);assert.equal(parseCount('1.2亿收藏').value,120000000)});
test('missing and malformed counts remain unknown',()=>{for(const x of [null,undefined,'暂无','-1','1.5收藏','9万+收藏']) assert.equal(parseCount(x).value,null)});
test('ranking preserves source and long string IDs',()=>{const x=parseRanking(ranking(1,1,[row('7687919221593885758')]),opts);assert.equal(x.items[0].seriesId,'7687919221593885758');assert.equal(x.items[0].observation.sourceFormat,'embedded_json');assert.equal(x.items[0].collection.value,1243000)});
test('wrong pages and unsafe numeric IDs reject',()=>{assert.throws(()=>parseRanking(ranking(2,2),opts));assert.throws(()=>parseRanking(ranking(1,1,[row(123)]),opts))});
test('page scripts never execute',()=>{globalThis.__hongguoTest=0;parseRanking(ranking()+'<script>globalThis.__hongguoTest=1</script>',opts);assert.equal(globalThis.__hongguoTest,0);delete globalThis.__hongguoTest});
test('detail keeps distinct metrics and validates requested ID',()=>{const x=parseDetail(detail(),{seriesId:'123',sourceUrl:origin+'/detail?series_id=123',fetchedAt:stamp});assert.equal(x.collection.value,1200123);assert.equal(x.likes.value,900);assert.equal(x.heat.value,2001);assert.throws(()=>parseDetail(detail('456'),{seriesId:'123'}))});
test('only real same-series player anchors are exposed',()=>{const o={seriesId:'123',sourceUrl:origin+'/detail?series_id=123',fetchedAt:stamp};assert.equal(parseDetail(detail()+'<a href="/player/123">播放</a>',o).watchPageUrl,origin+'/player/123');for(const extra of ['<a data-href="/player/123">伪</a>','<!--<a href="/player/123">伪</a>-->','<script>"<a href=\'/player/123\'>"</script>','<a href="https://example.com/player/123">伪</a>'])assert.equal(parseDetail(detail()+extra,o).watchPageUrl,null)});
test('search validates query and returns bounded source window',()=>{const x=parseSearch(search(),{query:'剧',sourceUrl:origin+'/search/x',fetchedAt:stamp});assert.equal(x.items.length,1);assert.equal(x.sourceReportedTotal,'100');assert.throws(()=>parseSearch(search(),{query:'错'}))});
test('unfinished streams remain distinguishable',()=>{const args=JSON.stringify(['x',[{key:'content',routerDataFnName:'s',routerDataFnArgs:['"x"','"content"']}]]).replaceAll('&','&amp;').replaceAll('"','&quot;');assert.throws(()=>routeData(`<script data-fn-name="mergeLoaderData" data-fn-args="${args}"></script>`,'x'),IncompletePageError)});
test('dedup preserves conflicts and conservative threshold',()=>{const a=parseRanking(ranking(1,1,[row('123','99.9万收藏')]),opts).items;const b=parseRanking(ranking(1,1,[row('123','120万收藏')]),opts).items;const [r]=deduplicate([...a,...b]);assert.equal(r.observations.length,2);assert.equal(r.conflicts.length,1);assert.equal(r.collection.value,999000);assert.equal(thresholdStatus(r,1000000),'uncertain')});
test('rounded boundary and unknown are not definite matches',()=>{for(const [value,want] of [['100万收藏','uncertain'],[null,'unknown'],['200万收藏','meets']]){const [r]=deduplicate(parseRanking(ranking(1,1,[row('123',value)]),opts).items);assert.equal(thresholdStatus(r,1000000),want)}});
test('all four boards and five pages are traversed',async()=>{let n=0;const c=client(async u=>{n++;const url=new URL(u),p=Number(url.searchParams.get('page')??1),b=url.pathname.split('/').at(-1);return resp(ranking(p,5,[row(String(n),'50万收藏',(p-1)*20+1)],b))});const r=await c.rankings();assert.equal(n,20);assert.equal(r.coverage.complete,true);assert.equal(r.items.length,20);c.dispose()});
test('partial failures remain explicit and later pages continue',async()=>{const c=client(async u=>{const p=Number(new URL(u).searchParams.get('page')??1);return p===2?resp('blocked',{status:429}):resp(ranking(p,3))});const r=await c.rankings({boards:['hot-drama']});assert.equal(r.coverage.pagesFetched,2);assert.equal(r.coverage.complete,false);assert.equal(r.coverage.failures.length,1);c.dispose()});
test('cache and refresh behavior',async()=>{let n=0;const c=client(async()=>{n++;return resp(detail())});await c.detail({seriesId:'123'});assert.equal((await c.detail({seriesId:'123'})).fromCache,true);await c.detail({seriesId:'123',refresh:true});assert.equal(n,2);c.dispose()});
test('parser errors are evicted from cache',async()=>{let n=0;const c=client(async()=>resp(++n===1?'captcha':detail()));await assert.rejects(()=>c.detail({seriesId:'123'}));await c.detail({seriesId:'123'});assert.equal(n,2);c.dispose()});
test('invalid options and config reject before network',async()=>{const c=client(()=>{throw new Error('network should not run')});await assert.rejects(()=>c.detail({seriesId:123}));await assert.rejects(()=>c.search({query:''}));await assert.rejects(()=>c.collections({minCollections:-1}));assert.throws(()=>resolveConfig({constructor:5}));c.dispose()});
test('foreign URLs, wrong content and oversize reject',async()=>{const c=client(async()=>resp('x'.repeat(2048)),{maxResponseBytes:1024});await assert.rejects(()=>c.page('https://example.com',false));await assert.rejects(()=>c.detail({seriesId:'123'}),/maxResponseBytes/);c.dispose()});
test('pre-abort and disposal block requests',async()=>{let n=0;const c=client(async()=>{n++;return resp(detail())});const a=new AbortController();a.abort();await assert.rejects(()=>c.detail({seriesId:'123'},a.signal));c.dispose();await assert.rejects(()=>c.detail({seriesId:'123'}));assert.equal(n,0)});
test('four tool definitions register, validate args and dispose',async()=>{const defs=[],disposers=[];apply({tools:{register:d=>{defs.push(d);return()=>{}}},effect:fn=>disposers.push(fn())});assert.equal(defs.length,4);for(const d of defs){assert.equal(d.parameters.type,'object');assert.ok(d.output.schema);assert.doesNotThrow(()=>JSON.stringify(d.parameters));await assert.rejects(()=>d.execute({bogus:1},{signal:new AbortController().signal}))}for(const d of disposers)d()});
test('search client does not equate returned window to source total',async()=>{const c=client(async()=>resp(search()));const r=await c.search({query:'剧'});assert.equal(r.complete,false);assert.equal(r.truncated,true);assert.equal(r.availableInWindow,1);c.dispose()});
